/* ---- begin verbatim ---- */
static struct zmk_led_hsb hsb_scale_min_max(struct zmk_led_hsb hsb) {
    hsb.b = CONFIG_ZMK_RGB_UNDERGLOW_BRT_MIN +
            (CONFIG_ZMK_RGB_UNDERGLOW_BRT_MAX - CONFIG_ZMK_RGB_UNDERGLOW_BRT_MIN) * hsb.b / BRT_MAX;
    return hsb;
}
/* ---- end verbatim ---- */

/* ---- begin verbatim ---- */
static struct zmk_led_hsb hsb_scale_zero_max(struct zmk_led_hsb hsb) {
    hsb.b = hsb.b * CONFIG_ZMK_RGB_UNDERGLOW_BRT_MAX / BRT_MAX;
    return hsb;
}
/* ---- end verbatim ---- */

/* ---- begin verbatim ---- */
static struct led_rgb hsb_to_rgb(struct zmk_led_hsb hsb) {
    float r = 0, g = 0, b = 0;

    uint8_t i = hsb.h / 60;
    float v = hsb.b / ((float)BRT_MAX);
    float s = hsb.s / ((float)SAT_MAX);
    float f = hsb.h / ((float)HUE_MAX) * 6 - i;
    float p = v * (1 - s);
    float q = v * (1 - f * s);
    float t = v * (1 - (1 - f) * s);

    switch (i % 6) {
    case 0:
        r = v;
        g = t;
        b = p;
        break;
    case 1:
        r = q;
        g = v;
        b = p;
        break;
    case 2:
        r = p;
        g = v;
        b = t;
        break;
    case 3:
        r = p;
        g = q;
        b = v;
        break;
    case 4:
        r = t;
        g = p;
        b = v;
        break;
    case 5:
        r = v;
        g = p;
        b = q;
        break;
    }

    struct led_rgb rgb = {r : r * 255, g : g * 255, b : b * 255};

    return rgb;
}
/* ---- end verbatim ---- */

/* ---- begin verbatim: LED_RGB scaling ---- */
#define LED_RGB_SCALING_MULTIPLE (((float)CONFIG_ZMK_RGB_UNDERGLOW_BRT_SCALE) / 250.)

#define LED_RGB(hex)                                                                               \
    ((struct led_rgb){                                                                             \
        r : LED_RGB_SCALING_MULTIPLE * (((hex) & 0xFF0000) >> 16),                                 \
        g : LED_RGB_SCALING_MULTIPLE * (((hex) & 0x00FF00) >> 8),                                  \
        b : LED_RGB_SCALING_MULTIPLE * (((hex) & 0x0000FF) >> 0)                                   \
    })
/* ---- end verbatim ---- */

/* ---- begin verbatim: central send, colours, layer map, blink, kinesis effect ---- */
#if ZMK_BLE_IS_CENTRAL
static struct k_work_delayable led_update_work;

static void zmk_rgb_underglow_central_send() {
    int err = zmk_split_bt_update_led(&led_data);
    if (err) {
        LOG_ERR("send failed (err %d)", err);
    }
}

#define NUM_BT_COLORS 4

static const struct led_rgb BT_COLORS[NUM_BT_COLORS] = {LED_RGB(0xFFFFFF), LED_RGB(0x0000FF),
                                                        LED_RGB(0xFF0000), LED_RGB(0x00FF00)};
#endif

static const struct led_rgb LAYER_COLORS[8] = {
    LED_RGB(0x000000), LED_RGB(0xFFFFFF), LED_RGB(0x0000FF), LED_RGB(0x00FF00),
    LED_RGB(0xFF0000), LED_RGB(0xFF00FF), LED_RGB(0x00FFFF), LED_RGB(0xFFFF00)};

// Formulas chosen so that for the first 8 layers both left and right modules show the same color,
// then as the layer number increases the right module color cycles through until "wrapping around",
// at which point the left module colour is advanced by one as well. We skip over the off/black
// state while we do this. (The right module also skips over the current left module color each
// loop, since those combinations correspond to the first 8 layers.)
static void zmk_led_layer_to_colors(uint8_t layer, uint8_t *left, uint8_t *right) {
    if (layer < 8) {
        *left = layer;
        *right = layer;
        return;
    }

    *left = 1 + ((layer - 8) / 6);
    *right = 1 + ((layer - 8) % 6);

    if (*left <= *right)
        *right += 1;
}

static bool zmk_kinesis_blink_step(uint8_t idx, uint8_t limit) {
    state.animation_step++;
    if (state.animation_step > limit) {
        last_ble_state[idx] = !last_ble_state[idx];
        state.animation_step = 0;
    }

    return !last_ble_state[idx];
}

static struct led_rgb zmk_get_indicator_color(zmk_hid_indicators_t bit) {
    return led_data.indicators & bit ? LED_RGB(CONFIG_ZMK_RGB_UNDERGLOW_MOD_COLOR)
                                     : LED_RGB(0x000000);
}

static void zmk_rgb_underglow_effect_kinesis() {
#if ZMK_BLE_IS_CENTRAL
    // update state and propagate to peripheral if necessary
    old_led_data.layer = led_data.layer;
    old_led_data.indicators = led_data.indicators;
    led_data.indicators = zmk_hid_indicators_get_current_profile();
    led_data.layer = zmk_keymap_highest_layer_active();

    if (old_led_data.layer != led_data.layer || old_led_data.indicators != led_data.indicators) {
        zmk_rgb_underglow_central_send();
    }
#endif

    bool bt_blinking = false;

    uint8_t layer_color_left, layer_color_right;
    zmk_led_layer_to_colors(led_data.layer, &layer_color_left, &layer_color_right);

#if ZMK_BLE_IS_CENTRAL
    // leds for central (left) side

    // set first led to caps lock state
    pixels[0] = zmk_get_indicator_color(ZMK_LED_CAPSLOCK_BIT);

    // set second led to bluetooth state, blinking quickly if bluetooth not paired,
    // and slowly if not connected
    int bt_idx = zmk_ble_active_profile_index();
    if (zmk_ble_active_profile_is_open()) {
        bt_blinking = zmk_kinesis_blink_step(0, 2);
    } else if (!zmk_ble_active_profile_is_connected()) {
        bt_blinking = zmk_kinesis_blink_step(1, 13);
    }
    pixels[1] = (bt_idx < NUM_BT_COLORS && !bt_blinking) ? BT_COLORS[bt_idx] : LED_RGB(0x000000);

    // set third led to layer state
    pixels[2] = LAYER_COLORS[layer_color_left];
#else
    // leds for peripheral (right) side

    // set first and second leds to num lock and scroll lock state, respectively
    pixels[2] = zmk_get_indicator_color(ZMK_LED_NUMLOCK_BIT);
    pixels[1] = zmk_get_indicator_color(ZMK_LED_SCROLLLOCK_BIT);

    // set third led to layer state
    pixels[0] = LAYER_COLORS[layer_color_right];

#if IS_ENABLED(CONFIG_ZMK_SPLIT_BLE)
    bool bt_alert = false;
    if (!zmk_split_bt_peripheral_is_bonded()) {
        bt_alert = true;
        bt_blinking = zmk_kinesis_blink_step(0, 2);
    } else if (!zmk_split_bt_peripheral_is_connected()) {
        bt_alert = true;
        bt_blinking = zmk_kinesis_blink_step(1, 13);
    }

    if (bt_alert) {
        // override all leds to blinking red due to bluetooth problem
        struct led_rgb color = bt_blinking ? LED_RGB(0x000000) : LED_RGB(0xFF0000);
        for (int i = 0; i < STRIP_NUM_PIXELS; i++)
            pixels[i] = color;
    }
#endif
#endif
}
/* ---- end verbatim ---- */

/* ---- begin verbatim ---- */
static void zmk_rgb_underglow_effect_solid(void) {
    for (int i = 0; i < STRIP_NUM_PIXELS; i++) {
        pixels[i] = hsb_to_rgb(hsb_scale_min_max(state.color));
    }
}
/* ---- end verbatim ---- */

/* ---- begin verbatim ---- */
static void zmk_rgb_underglow_effect_breathe(void) {
    for (int i = 0; i < STRIP_NUM_PIXELS; i++) {
        struct zmk_led_hsb hsb = state.color;
        hsb.b = abs(state.animation_step - 1200) / 12;

        pixels[i] = hsb_to_rgb(hsb_scale_zero_max(hsb));
    }

    state.animation_step += state.animation_speed * 10;

    if (state.animation_step > 2400) {
        state.animation_step = 0;
    }
}
/* ---- end verbatim ---- */

/* ---- begin verbatim ---- */
static void zmk_rgb_underglow_effect_spectrum(void) {
    for (int i = 0; i < STRIP_NUM_PIXELS; i++) {
        struct zmk_led_hsb hsb = state.color;
        hsb.h = state.animation_step;

        pixels[i] = hsb_to_rgb(hsb_scale_min_max(hsb));
    }

    state.animation_step += state.animation_speed;
    state.animation_step = state.animation_step % HUE_MAX;
}
/* ---- end verbatim ---- */

/* ---- begin verbatim ---- */
static void zmk_rgb_underglow_effect_swirl(void) {
    for (int i = 0; i < STRIP_NUM_PIXELS; i++) {
        struct zmk_led_hsb hsb = state.color;
        hsb.h = (HUE_MAX / STRIP_NUM_PIXELS * i + state.animation_step) % HUE_MAX;

        pixels[i] = hsb_to_rgb(hsb_scale_min_max(hsb));
    }

    state.animation_step += state.animation_speed * 2;
    state.animation_step = state.animation_step % HUE_MAX;
}
/* ---- end verbatim ---- */

/* ---- begin verbatim ---- */
static void zmk_rgb_underglow_effect_test() {
    triggered = true;
    struct led_rgb rgb;
    rgb.r = 0;
    rgb.g = 0;
    rgb.b = 0;

    for (int i = 0; i < STRIP_NUM_PIXELS; i++) {
        struct zmk_led_hsb hsb = state.color;
        hsb.h = state.animation_step;

        pixels[i] = hsb_to_rgb(hsb_scale_min_max(hsb));
    }
    if (state.animation_step < (HUE_MAX * 3)) {
        struct zmk_led_hsb hsb = state.color;
        hsb.h = state.animation_step;
        rgb.r = 0;

        pixels[0] = rgb;
        pixels[1] = rgb;
        pixels[2] = hsb_to_rgb(hsb_scale_min_max(hsb));
    }
    if (state.animation_step < (HUE_MAX * 2)) {
        struct zmk_led_hsb hsb = state.color;
        hsb.h = state.animation_step - HUE_MAX;
        rgb.r = 0;
        rgb.g = 0;
        rgb.b = 0;
        pixels[0] = rgb;
        pixels[1] = hsb_to_rgb(hsb_scale_min_max(hsb));
        pixels[2] = rgb;
    }
    if (state.animation_step < HUE_MAX) {
        struct zmk_led_hsb hsb = state.color;
        hsb.h = state.animation_step;
        rgb.r = 0;
        rgb.g = 0;
        rgb.b = 0;
        pixels[0] = hsb_to_rgb(hsb_scale_min_max(hsb));
        pixels[1] = rgb;
        pixels[2] = rgb;
    }

    state.animation_step += 20;
    if (state.animation_step > (HUE_MAX * 3)) {
        rgb.r = 255;
        rgb.g = 255;
        rgb.b = 255;
        for (int i = 0; i < STRIP_NUM_PIXELS; i++)
            pixels[i] = rgb;
    }
}
/* ---- end verbatim ---- */

/* ---- begin verbatim: battery effect ---- */
#define NUM_BATTERY_LEVELS 3

static const uint8_t BATTERY_LEVELS[NUM_BATTERY_LEVELS] = {80, 50, 20};

static const struct led_rgb BATTERY_COLORS[NUM_BATTERY_LEVELS + 1] = {
    LED_RGB(0x00FF00), LED_RGB(0xFFFF00), LED_RGB(0xFF8C00), LED_RGB(0xFF0000)};
static void zmk_rgb_underglow_effect_battery() {
    uint8_t soc = zmk_battery_state_of_charge();

    int color = 0;
    for (; color < NUM_BATTERY_LEVELS && soc < BATTERY_LEVELS[color]; color++)
        ;

    struct led_rgb rgb = BATTERY_COLORS[color];
    for (int i = 0; i < STRIP_NUM_PIXELS; i++) {
        pixels[i] = rgb;
    }
}
/* ---- end verbatim ---- */

/* ---- begin verbatim: state, commands ---- */

static int zmk_rgb_underglow_save_state(void) { return 0; }
static int zmk_rgb_underglow_on(void) {
    if (!led_strip)
        return -ENODEV;

#if IS_ENABLED(CONFIG_ZMK_RGB_UNDERGLOW_EXT_POWER)
    if (ext_power != NULL) {
        int rc = ext_power_enable(ext_power);
        if (rc != 0) {
            LOG_ERR("Unable to enable EXT_POWER: %d", rc);
        }
    }
#endif

    state.on = true;
    state.animation_step = 0;
    k_timer_start(&underglow_tick, K_NO_WAIT, K_MSEC(50));

#if ZMK_BLE_IS_CENTRAL
    led_data.on = true;
    zmk_rgb_underglow_central_send();
#endif

    return 0;
}

static void zmk_rgb_underglow_off_handler(struct k_work *work) {
    for (int i = 0; i < STRIP_NUM_PIXELS; i++) {
        pixels[i] = (struct led_rgb){r : 0, g : 0, b : 0};
    }

    led_strip_update_rgb(led_strip, pixels, STRIP_NUM_PIXELS);
}

static int zmk_rgb_underglow_off(void) {
    if (!led_strip)
        return -ENODEV;

#if IS_ENABLED(CONFIG_ZMK_RGB_UNDERGLOW_EXT_POWER)
    if (ext_power != NULL) {
        int rc = ext_power_disable(ext_power);
        if (rc != 0) {
            LOG_ERR("Unable to disable EXT_POWER: %d", rc);
        }
    }
#endif

    k_work_submit_to_queue(zmk_workqueue_lowprio_work_q(), &underglow_off_work);

    k_timer_stop(&underglow_tick);
    state.on = false;
#if ZMK_BLE_IS_CENTRAL
    led_data.on = false;
    zmk_rgb_underglow_central_send();
#endif
    return 0;
}

static int zmk_rgb_underglow_calc_effect(int direction) {
    return (state.current_effect + UNDERGLOW_EFFECT_NUMBER + direction) % UNDERGLOW_EFFECT_NUMBER;
}

static int zmk_rgb_underglow_select_effect(int effect) {
    if (!led_strip)
        return -ENODEV;

    if (effect < 0 || effect >= UNDERGLOW_EFFECT_NUMBER) {
        return -EINVAL;
    }

    state.current_effect = effect;
    state.animation_step = 0;

#if ZMK_BLE_IS_CENTRAL
    led_data.effect = effect;

    zmk_rgb_underglow_central_send();
#endif

    return 0;
}

static int zmk_rgb_underglow_cycle_effect(int direction) {
    return zmk_rgb_underglow_select_effect(zmk_rgb_underglow_calc_effect(direction));
}

static int zmk_rgb_underglow_toggle(void) {
    return state.on ? zmk_rgb_underglow_off() : zmk_rgb_underglow_on();
}

static int zmk_rgb_underglow_set_hsb(struct zmk_led_hsb color) {
    if (color.h > HUE_MAX || color.s > SAT_MAX || color.b > BRT_MAX) {
        return -ENOTSUP;
    }

    state.color = color;

    return 0;
}

static struct zmk_led_hsb zmk_rgb_underglow_calc_hue(int direction) {
    struct zmk_led_hsb color = state.color;

    color.h += HUE_MAX + (direction * CONFIG_ZMK_RGB_UNDERGLOW_HUE_STEP);
    color.h %= HUE_MAX;

    return color;
}

static struct zmk_led_hsb zmk_rgb_underglow_calc_sat(int direction) {
    struct zmk_led_hsb color = state.color;

    int s = color.s + (direction * CONFIG_ZMK_RGB_UNDERGLOW_SAT_STEP);
    if (s < 0) {
        s = 0;
    } else if (s > SAT_MAX) {
        s = SAT_MAX;
    }
    color.s = s;

    return color;
}

static struct zmk_led_hsb zmk_rgb_underglow_calc_brt(int direction) {
    struct zmk_led_hsb color = state.color;

    int b = color.b + (direction * CONFIG_ZMK_RGB_UNDERGLOW_BRT_STEP);
    color.b = CLAMP(b, 0, BRT_MAX);

    return color;
}

static int zmk_rgb_underglow_change_hue(int direction) {
    if (!led_strip)
        return -ENODEV;

    state.color = zmk_rgb_underglow_calc_hue(direction);

    return zmk_rgb_underglow_save_state();
}

static int zmk_rgb_underglow_change_sat(int direction) {
    if (!led_strip)
        return -ENODEV;

    state.color = zmk_rgb_underglow_calc_sat(direction);

    return zmk_rgb_underglow_save_state();
}

static int zmk_rgb_underglow_change_brt(int direction) {
    if (!led_strip)
        return -ENODEV;

    state.color = zmk_rgb_underglow_calc_brt(direction);

    return zmk_rgb_underglow_save_state();
}

static int zmk_rgb_underglow_change_spd(int direction) {
    if (!led_strip)
        return -ENODEV;

    if (state.animation_speed == 1 && direction < 0) {
        return 0;
    }

    state.animation_speed += direction;

    if (state.animation_speed > 5) {
        state.animation_speed = 5;
    }

    return zmk_rgb_underglow_save_state();
}

/* ---- end verbatim ---- */

/* ---- begin verbatim: initial state (zmk_rgb_underglow_init) ---- */
static void fork_init_state(void) {
    state = (struct rgb_underglow_state){
        color : {
            h : CONFIG_ZMK_RGB_UNDERGLOW_HUE_START,
            s : CONFIG_ZMK_RGB_UNDERGLOW_SAT_START,
            b : CONFIG_ZMK_RGB_UNDERGLOW_BRT_START,
        },
        animation_speed : CONFIG_ZMK_RGB_UNDERGLOW_SPD_START,
        current_effect : CONFIG_ZMK_RGB_UNDERGLOW_EFF_START,
        animation_step : 0,
        on : IS_ENABLED(CONFIG_ZMK_RGB_UNDERGLOW_ON_START)
    };
    led_data.indicators = 0;
    led_data.on = IS_ENABLED(CONFIG_ZMK_RGB_UNDERGLOW_ON_START);
    led_data.effect = state.current_effect;
}
/* ---- end verbatim ---- */

/* ---- begin verbatim: effect dispatcher (zmk_rgb_underglow_tick, minus the strip update) ---- */
static void fork_dispatch_effect(void) {
switch (state.current_effect) {
    case UNDERGLOW_EFFECT_SOLID:
        zmk_rgb_underglow_effect_solid();
        break;
    case UNDERGLOW_EFFECT_BREATHE:
        zmk_rgb_underglow_effect_breathe();
        break;
    case UNDERGLOW_EFFECT_SPECTRUM:
        zmk_rgb_underglow_effect_spectrum();
        break;
    case UNDERGLOW_EFFECT_SWIRL:
        zmk_rgb_underglow_effect_swirl();
        break;
    case UNDERGLOW_EFFECT_KINESIS:
        zmk_rgb_underglow_effect_kinesis();
        break;
    case UNDERGLOW_EFFECT_BATTERY:
        zmk_rgb_underglow_effect_battery();
        break;
    case UNDERGLOW_EFFECT_TEST:
        zmk_rgb_underglow_effect_test();
        break;
    }
}
/* ---- end verbatim ---- */


/* ------------------------------------------------------------------------------------------ */
/* Test entry points                                                                          */

void FORK_NAME(reset)(void) {
    static const struct device dev;
    led_strip = &dev;
    memset(&state, 0, sizeof(state));
    memset(&led_data, 0, sizeof(led_data));
    memset(last_ble_state, 0, sizeof(last_ble_state));
#if ZMK_BLE_IS_CENTRAL
    memset(&old_led_data, 0, sizeof(old_led_data));
#endif
    memset(pixels, 0, sizeof(pixels));
    memset(&world, 0, sizeof(world));
    fork_init_state();
}

/* One 50 ms tick of the current effect, as the fork's timer would run it while the strip is on. */
void FORK_NAME(tick)(const struct stub_world *w, struct led_rgb out[3]) {
    world = *w;
#if !ZMK_BLE_IS_CENTRAL
    /* The peripheral gets layer + indicators pushed from the central instead of reading them. */
    led_data.layer = w->highest_layer;
    led_data.indicators = w->hid_indicators;
#endif
    fork_dispatch_effect();
    memcpy(out, pixels, sizeof(pixels));
}

void FORK_NAME(battery)(uint8_t soc, struct led_rgb out[3]) {
    world.soc = soc;
    zmk_rgb_underglow_effect_battery();
    memcpy(out, pixels, sizeof(pixels));
}

struct fork_state_view {
    uint16_t h;
    uint8_t s, b, speed, effect;
    uint16_t step;
    bool on;
};

void FORK_NAME(state)(struct fork_state_view *v) {
    v->h = state.color.h;
    v->s = state.color.s;
    v->b = state.color.b;
    v->speed = state.animation_speed;
    v->effect = state.current_effect;
    v->step = state.animation_step;
    v->on = state.on;
}

/* Commands, by the same names the `&rgb_ug` behavior calls them. Returns the fork's own result. */
enum fork_cmd {
    FORK_ON, FORK_OFF, FORK_TOGGLE, FORK_SELECT, FORK_CYCLE, FORK_SET_HSB,
    FORK_HUE, FORK_SAT, FORK_BRT, FORK_SPD,
};

int FORK_NAME(cmd)(enum fork_cmd c, int a, int b, int d) {
    switch (c) {
    case FORK_ON: return zmk_rgb_underglow_on();
    case FORK_OFF: return zmk_rgb_underglow_off();
    case FORK_TOGGLE: return zmk_rgb_underglow_toggle();
    case FORK_SELECT: return zmk_rgb_underglow_select_effect(a);
    case FORK_CYCLE: return zmk_rgb_underglow_cycle_effect(a);
    case FORK_SET_HSB: return zmk_rgb_underglow_set_hsb((struct zmk_led_hsb){.h = a, .s = b, .b = d});
    case FORK_HUE: return zmk_rgb_underglow_change_hue(a);
    case FORK_SAT: return zmk_rgb_underglow_change_sat(a);
    case FORK_BRT: return zmk_rgb_underglow_change_brt(a);
    case FORK_SPD: return zmk_rgb_underglow_change_spd(a);
    }
    return -1;
}
